insert into public.site_settings (id, site_name_ar, site_name_en, doctor_name_ar, doctor_name_en, doctor_role_ar, doctor_role_en, doctor_tagline_ar, doctor_tagline_en, monogram, logo_id, favicon_id, portrait_id, default_title_ar, default_title_en, default_description_ar, default_description_en, og_image_id, site_url, default_locale, robots_index, whatsapp_digits, whatsapp_message_ar, whatsapp_message_en, email, address_ar, address_en, hours_ar, hours_en, map_embed_url, map_link_url) values
  (1, 'د. محمد جمال', 'Dr. Mohamed Gamal', 'د. محمد جمال', 'Dr. Mohamed Gamal', 'طبيب العلاج الطبيعي والتأهيل', 'Physiotherapy & Rehabilitation Doctor', 'علاج طبيعي وتأهيل', 'Physiotherapy & Rehab', 'MG', '452019b1-ce5f-5c51-b643-40b131483611', null, null, 'د. محمد جمال | العلاج الطبيعي والتأهيل', 'Dr. Mohamed Gamal | Physiotherapy & Rehabilitation', 'د. محمد جمال — طبيب العلاج الطبيعي والتأهيل. برامج علاج مخصّصة لتخفيف الألم واستعادة الحركة والعودة إلى حياتك اليومية بثقة.', 'Dr. Mohamed Gamal — Physiotherapy and Rehabilitation Doctor. Personalised treatment plans to ease pain, restore movement and get you back to everyday life with confidence.', '8952200c-3175-5df6-8d6f-d8afc09d5847', '', 'ar', true, '201146540705', 'مرحباً د. محمد، أرغب في حجز موعد.', 'Hello Dr. Mohamed, I''d like to book an appointment.', '', '[[عنوان العيادة بالتفصيل]]', '[[Full clinic address]]', '[[أيام وساعات العمل]]', '[[Working days and hours]]', '', '')
