insert into public.pages (key, path, sort_order, name_ar, name_en, seo_title_ar, seo_title_en, seo_description_ar, seo_description_en, og_title_ar, og_title_en, og_description_ar, og_description_en, og_image_id, canonical_url, robots_index, robots_follow, twitter_card) values
  ('home', '/', 10, 'الرئيسية', 'Home', '', '', 'برامج علاج طبيعي مصمّمة لك وحدك، لتخفيف الألم واستعادة القوة والعودة إلى حياتك اليومية بثقة.', 'Physiotherapy programmes designed around you — to ease pain, rebuild strength and return to everyday life with confidence.', '', '', '', '', null, '', true, true, 'summary_large_image'),
  ('about', '/about', 20, 'عن الطبيب', 'About', 'عن الطبيب', 'About', 'تعرّف على د. محمد جمال، وعلى الفلسفة التي يقوم عليها كل برنامج تأهيل.', 'Get to know Dr. Mohamed Gamal and the philosophy behind every rehabilitation plan.', '', '', '', '', null, '', true, true, 'summary_large_image'),
  ('services', '/services', 30, 'الخدمات', 'Services', 'الخدمات', 'Services', 'من التقييم الأول حتى العودة الكاملة للحركة — خطة علاج واضحة لكل مرحلة.', 'From the first assessment to full return to movement — a clear plan for every stage.', '', '', '', '', null, '', true, true, 'summary_large_image'),
  ('videos', '/videos', 40, 'الفيديوهات', 'Videos', 'الفيديوهات', 'Videos', 'تمارين ونصائح عملية تساعدك على فهم حالتك والاستمرار في تعافيك من المنزل.', 'Practical exercises and advice to help you understand your condition and keep progressing at home.', '', '', '', '', null, '', true, true, 'summary_large_image'),
  ('articles', '/articles', 50, 'المقالات', 'Articles', 'المقالات', 'Articles', 'مقالات مبسّطة عن الألم والحركة والوقاية، لتتخذ قرارات أفضل بشأن صحتك.', 'Clear, simple articles on pain, movement and prevention — so you can make better decisions about your health.', '', '', '', '', null, '', true, true, 'summary_large_image'),
  ('contact', '/contact', 60, 'تواصل', 'Contact', 'تواصل', 'Contact', 'احجز موعدك أو اسأل عن حالتك عبر الهاتف أو واتساب — خطوتك الأولى تبدأ برسالة.', 'Book a visit or ask about your condition by phone or WhatsApp — your first step starts with a message.', '', '', '', '', null, '', true, true, 'summary_large_image'),
  ('global', null, 70, 'عناصر مشتركة', 'Shared elements', '', '', '', '', '', '', '', '', null, '', true, true, 'summary_large_image')
insert into public.page_sections (id, page_key, key, type, sort_order, visible, content, published_at) values
  ('fc7057cb-7c09-5f9f-8ea1-90f6d2b5965c', 'home', 'hero', 'hero', 10, true, '{"eyebrow":{"ar":"العلاج الطبيعي والتأهيل","en":"Physiotherapy & Rehabilitation"},"titleLead":{"ar":"استعِد","en":"Move"},"titleAccent":{"ar":"حركتك","en":"Again"},"subtitle":{"ar":"برامج علاج طبيعي مصمّمة لك وحدك، لتخفيف الألم واستعادة القوة والعودة إلى حياتك اليومية بثقة.","en":"Physiotherapy programmes designed around you — to ease pain, rebuild strength and return to everyday life with confidence."},"image":{"id":"8952200c-3175-5df6-8d6f-d8afc09d5847","position":""},"primaryCta":{"label":{"ar":"احجز تقييمك الأول","en":"Book your assessment"},"href":"/contact#booking"},"secondaryCta":{"label":{"ar":"استكشف الخدمات","en":"Explore services"},"href":"/services"},"badges":[{"icon":"Route","label":{"ar":"خطة علاج مخصّصة","en":"Personal treatment plan"}},{"icon":"TrendingUp","label":{"ar":"متابعة مستمرة","en":"Continuous follow-up"}},{"icon":"House","label":{"ar":"تمارين منزلية","en":"Home exercises"}}]}'::jsonb, null),
  ('1defebbc-75ad-5ac6-b367-cfb46c1b3e83', 'home', 'ticker', 'ticker', 20, true, '{}'::jsonb, null),
  ('ea7fb350-587a-571c-8ee6-ea0ca00cab2a', 'home', 'intro', 'homeIntro', 30, true, '{"eyebrow":{"ar":"تعرّف على الطبيب","en":"Meet the doctor"},"title":{"ar":"علاج يبدأ بالإنصات، وينتهي بعودتك إلى الحركة","en":"Care that starts by listening — and ends with you moving again"},"paragraphs":{"ar":["د. محمد جمال طبيب العلاج الطبيعي والتأهيل، يؤمن بأن لكل مريض قصة مختلفة، وأن العلاج الناجح يبدأ بفهم هذه القصة جيداً.","[[نبذة قصيرة عن خبرة الطبيب ومجالات تخصّصه — تُضاف من الطبيب.]]"],"en":["Dr. Mohamed Gamal is a physiotherapy and rehabilitation doctor who believes every patient has a different story, and that successful treatment starts by understanding it.","[[A short summary of the doctor''s experience and areas of focus — to be provided by the doctor.]]"]},"points":[{"icon":"SearchCheck","title":{"ar":"تقييم دقيق","en":"Precise assessment"},"text":{"ar":"نحدّد مصدر الألم قبل البدء بالعلاج.","en":"We find the source of pain before treating it."}},{"icon":"Route","title":{"ar":"خطة واضحة","en":"A clear plan"},"text":{"ar":"أهداف مرحلية تعرفها من اليوم الأول.","en":"Staged goals you know from day one."}},{"icon":"HandHeart","title":{"ar":"رعاية شخصية","en":"Personal care"},"text":{"ar":"متابعة قريبة في كل مرحلة.","en":"Close follow-up at every stage."}}],"signatureRole":{"ar":"طبيب العلاج الطبيعي والتأهيل","en":"Physiotherapy & Rehabilitation Doctor"},"cta":{"label":{"ar":"تعرّف على الطبيب","en":"Meet the doctor"},"href":"/about"},"image":{"id":"e72f8580-56b1-5a3f-a361-a3dd4a6ba2a9","position":""},"secondaryImage":{"id":"b1b90038-356e-5254-b0ff-fd1941e001f3","position":""}}'::jsonb, null),
  ('04018cd0-6f2d-58b3-bbcc-2158d6c9686b', 'home', 'services', 'homeServices', 40, true, '{"heading":{"eyebrow":{"ar":"الخدمات الأساسية","en":"Core services"},"title":{"ar":"علاج يناسب حالتك، لا حالة عامة","en":"Treatment built for your condition, not a template"},"text":{"ar":"مجموعة متكاملة من خدمات العلاج الطبيعي والتأهيل، تُختار وتُرتّب حسب تقييم كل مريض.","en":"A complete range of physiotherapy and rehabilitation services, selected and sequenced from each patient''s assessment."}},"cta":{"label":{"ar":"كل الخدمات","en":"All services"},"href":"/services"}}'::jsonb, null),
  ('83515ed1-fb2f-5aa6-9ac0-3f6a26919058', 'home', 'why', 'features', 50, true, '{"heading":{"eyebrow":{"ar":"لماذا د. محمد جمال؟","en":"Why Dr. Mohamed Gamal?"},"title":{"ar":"رعاية تجمع بين العلم والاهتمام الإنساني","en":"Care that unites science and genuine attention"},"text":{"ar":"نتعامل مع الألم كمشكلة لها سبب، ومع المريض كشريك في رحلة التعافي.","en":"We treat pain as a problem with a cause — and every patient as a partner in recovery."}},"items":[{"icon":"ScanSearch","title":{"ar":"التشخيص قبل العلاج","en":"Diagnosis before treatment"},"text":{"ar":"تقييم شامل للحركة والقوة والوضعيات لتحديد السبب الحقيقي للألم.","en":"A full assessment of movement, strength and posture to find the real cause of pain."}},{"icon":"Target","title":{"ar":"أهداف قابلة للقياس","en":"Measurable goals"},"text":{"ar":"نحدّد معك أهدافاً واضحة ونقيس التقدّم في كل مرحلة.","en":"Clear goals set together, with progress measured at every stage."}},{"icon":"Dumbbell","title":{"ar":"علاج نشط","en":"Active treatment"},"text":{"ar":"التمارين جزء أساسي من الخطة لتبني قوة تدوم بعد انتهاء الجلسات.","en":"Exercise is central to the plan, building strength that lasts beyond your sessions."}},{"icon":"BookOpen","title":{"ar":"توعية وتمكين","en":"Education & empowerment"},"text":{"ar":"نشرح لك حالتك وكيف تحمي نفسك من عودة الألم.","en":"We explain your condition and how to protect yourself from recurring pain."}}],"image":{"id":"74e0101e-ee6c-51e2-872c-18eaee8bb3b6","position":""}}'::jsonb, null),
  ('23c5261b-7038-517d-a640-0f28fe8ea0bf', 'home', 'specialties', 'specialties', 60, true, '{"heading":{"eyebrow":{"ar":"مجالات العلاج","en":"Areas of care"},"title":{"ar":"اختر منطقة الألم لتتعرّف على الحالات الشائعة","en":"Choose where it hurts to see common conditions"},"text":{"ar":"نعالج طيفاً واسعاً من مشكلات الجهاز الحركي.","en":"We treat a wide range of musculoskeletal problems."}},"hint":{"ar":"مرّر المؤشر على أي منطقة للمعاينة، واضغط لتثبيتها","en":"Hover an area to preview it, click to pin it"},"cta":{"label":{"ar":"كل الخدمات","en":"All services"},"href":"/services"}}'::jsonb, null),
  ('5d6adeab-b92b-549c-818f-9e5040023c13', 'home', 'stats', 'stats', 70, true, '{"eyebrow":{"ar":"بالأرقام","en":"By the numbers"},"title":{"ar":"مسيرة تُقاس بتعافي المرضى","en":"A career measured in recoveries"},"image":{"id":"c04dbc0e-5772-5f45-8291-c77d4705ceb2","position":""}}'::jsonb, null),
  ('fe8c608e-6df2-5fdd-8002-387b0b96bc6a', 'home', 'journey', 'journey', 80, true, '{"heading":{"eyebrow":{"ar":"رحلة العلاج","en":"Your treatment journey"},"title":{"ar":"أربع خطوات واضحة من الألم إلى الحركة","en":"Four clear steps from pain to movement"},"text":{"ar":"تعرف من البداية ماذا سيحدث في كل مرحلة.","en":"You''ll know from the start what happens at each stage."}}}'::jsonb, null),
  ('26fd8452-b019-5ca2-8293-6a530f744f03', 'home', 'videos', 'homeVideos', 90, true, '{"heading":{"eyebrow":{"ar":"فيديوهات مختارة","en":"Featured videos"},"title":{"ar":"تمارين ونصائح يمكنك البدء بها اليوم","en":"Exercises and advice you can start today"}},"cta":{"label":{"ar":"مكتبة الفيديو كاملة","en":"Full video library"},"href":"/videos"}}'::jsonb, null),
