  ('ef313dc1-d85b-5a5f-81fc-b6382e1c4f96', 'about', 'hero', 'hero', 10, true, '{"eyebrow":{"ar":"عن الطبيب","en":"About the doctor"},"titleLead":{"ar":"طبيبك","en":"Meet Your"},"titleAccent":{"ar":"المعالج","en":"Therapist"},"subtitle":{"ar":"تعرّف على د. محمد جمال، وعلى الفلسفة التي يقوم عليها كل برنامج تأهيل.","en":"Get to know Dr. Mohamed Gamal and the philosophy behind every rehabilitation plan."},"image":{"id":"c04dbc0e-5772-5f45-8291-c77d4705ceb2","position":""},"primaryCta":null,"secondaryCta":null,"badges":[]}'::jsonb, null),
  ('a8674a1b-dad4-5b0e-943a-5193e45322c5', 'about', 'intro', 'aboutIntro', 20, true, '{"eyebrow":{"ar":"تعرّف على الطبيب","en":"Meet the doctor"},"title":{"ar":"د. محمد جمال","en":"Dr. Mohamed Gamal"},"paragraphs":{"ar":["طبيب العلاج الطبيعي والتأهيل. يرافق مرضاه من التقييم الأول حتى العودة إلى الحركة بثقة، عبر خطط علاج مخصّصة ومتابعة قريبة.","[[فقرة تعريفية عن الطبيب: التخصّص الدقيق، مكان العمل الحالي، ومجالات الاهتمام — تُضاف من الطبيب.]]"],"en":["Physiotherapy and rehabilitation doctor. He accompanies his patients from the first assessment to a confident return to movement, through personalised plans and close follow-up.","[[An introductory paragraph about the doctor: specialty focus, current practice and areas of interest — to be provided by the doctor.]]"]},"highlights":[{"icon":"GraduationCap","title":{"ar":"المؤهل","en":"Qualification"},"text":{"ar":"[[المؤهل العلمي الأساسي]]","en":"[[Primary qualification]]"}},{"icon":"Briefcase","title":{"ar":"الخبرة","en":"Experience"},"text":{"ar":"[[عدد سنوات الخبرة]]","en":"[[Years of experience]]"}},{"icon":"MapPin","title":{"ar":"العيادة","en":"Clinic"},"text":{"ar":"[[المدينة / العيادة]]","en":"[[City / clinic]]"}}]}'::jsonb, null),
  ('16f3f9be-dbad-516d-8d4b-0c0deaa37dff', 'about', 'bio', 'bio', 30, true, '{"eyebrow":{"ar":"النبذة المهنية","en":"Professional biography"},"title":{"ar":"مسيرة مهنية في خدمة الحركة","en":"A career devoted to movement"},"paragraphs":{"ar":["[[الفقرة الأولى من السيرة المهنية: بداية المسيرة والدراسة.]]","[[الفقرة الثانية: الخبرات العملية وأبرز المحطات المهنية.]]","[[الفقرة الثالثة: الاهتمامات الحالية ومجالات التطوير المستمر.]]"],"en":["[[First paragraph of the biography: early career and education.]]","[[Second paragraph: clinical experience and key professional milestones.]]","[[Third paragraph: current interests and continuing professional development.]]"]},"quote":{"ar":"[[اقتباس قصير بصوت الطبيب يلخّص رؤيته في العلاج.]]","en":"[[A short quote in the doctor''s own words summarising his approach to care.]]"}}'::jsonb, null),
