  ('268c9165-f839-5b30-af9b-127fdc1178ea', 'about', 'philosophy', 'philosophy', 80, true, '{"eyebrow":{"ar":"فلسفة العلاج","en":"Treatment philosophy"},"title":{"ar":"المريض شريك في التعافي، لا متلقٍّ له","en":"The patient is a partner in recovery, not a recipient of it"},"quote":{"ar":"الحركة هي الدواء الذي يصنعه الجسم بنفسه — ودورنا أن نرشده إلى الطريق الصحيح.","en":"Movement is the medicine the body makes for itself — our role is to guide it the right way."},"pillars":[{"icon":"Ear","title":{"ar":"نُنصت أولاً","en":"We listen first"},"text":{"ar":"كل خطة تبدأ بفهم قصتك وأهدافك وما يهمّك فعلاً.","en":"Every plan starts with your story, your goals and what truly matters to you."}},{"icon":"Activity","title":{"ar":"نُحرّك بأمان","en":"We move safely"},"text":{"ar":"تدرّج مدروس يبني القوة دون أن يتجاوز قدرة جسمك.","en":"Carefully graded progress that builds strength without overloading the body."}},{"icon":"Lightbulb","title":{"ar":"نُعلّم ونُمكّن","en":"We teach & empower"},"text":{"ar":"تفهم حالتك، فتصبح قادراً على حماية نفسك مستقبلاً.","en":"Understand your condition, and you can protect yourself in the future."}}],"image":{"id":"ee484e84-4396-5a3c-a1a8-08af003ae71c","position":""}}'::jsonb, null),
  ('29134196-c32d-566f-b4a8-0640846da305', 'about', 'values', 'values', 90, true, '{"heading":{"eyebrow":{"ar":"قيمنا","en":"Our values"},"title":{"ar":"ما نلتزم به مع كل مريض","en":"Our commitment to every patient"},"text":{"ar":"","en":""}},"items":[{"icon":"HandHeart","title":{"ar":"الاهتمام","en":"Care"},"text":{"ar":"رعاية إنسانية تحترم ظروف كل مريض.","en":"Human care that respects each patient''s circumstances."}},{"icon":"Eye","title":{"ar":"الشفافية","en":"Transparency"},"text":{"ar":"نوضّح التشخيص والخطة والتوقّعات بصدق.","en":"Honest explanations of diagnosis, plan and expectations."}},{"icon":"Target","title":{"ar":"الدقة","en":"Precision"},"text":{"ar":"قرارات علاجية مبنية على تقييم واضح.","en":"Treatment decisions grounded in clear assessment."}},{"icon":"ShieldCheck","title":{"ar":"الأمان","en":"Safety"},"text":{"ar":"تدرّج آمن يراعي حدود الجسم.","en":"Safe progression that respects the body''s limits."}},{"icon":"Repeat","title":{"ar":"الاستمرارية","en":"Continuity"},"text":{"ar":"متابعة منتظمة حتى تحقيق الأهداف.","en":"Regular follow-up until goals are reached."}},{"icon":"Handshake","title":{"ar":"الشراكة","en":"Partnership"},"text":{"ar":"نعمل معك، لا من أجلك فقط.","en":"We work with you, not just for you."}}]}'::jsonb, null),
  ('777dc1d8-ec72-5781-af2d-a5f3ec62b1a1', 'about', 'stats', 'stats', 100, true, '{"eyebrow":{"ar":"إنجازات","en":"Achievements"},"title":{"ar":"أثر يُقاس بالأرقام","en":"Impact you can measure"},"image":{"id":"74e0101e-ee6c-51e2-872c-18eaee8bb3b6","position":""}}'::jsonb, null),
  ('b985d1a7-d60e-5b4b-9380-64cc46287cbc', 'services', 'hero', 'hero', 10, true, '{"eyebrow":{"ar":"خدماتنا العلاجية","en":"Our treatments"},"titleLead":{"ar":"رعاية","en":"Complete"},"titleAccent":{"ar":"متكاملة","en":"Care"},"subtitle":{"ar":"من التقييم الأول حتى العودة الكاملة للحركة — خطة علاج واضحة لكل مرحلة.","en":"From the first assessment to full return to movement — a clear plan for every stage."},"image":{"id":"f68877e4-9d47-5af3-8493-56bf49d59ae2","position":""},"primaryCta":null,"secondaryCta":null,"badges":[]}'::jsonb, null),
  ('23a3154c-e98f-5ed7-b5af-86a1251c3837', 'services', 'intro', 'servicesIntro', 20, true, '{"eyebrow":{"ar":"كيف نساعدك","en":"How we help"},"title":{"ar":"خدمات علاج طبيعي مبنية على تقييم حالتك","en":"Physiotherapy services built on your assessment"},"paragraphs":{"ar":["لا توجد خطة علاج واحدة تناسب الجميع. نبدأ بتقييم شامل، ثم نختار من بين خدماتنا ما يناسب حالتك وأهدافك ونمط حياتك.","تجمع الخطة عادةً بين العلاج اليدوي والتمارين العلاجية والتوعية، مع متابعة منتظمة للتقدّم."],"en":["No single plan suits everyone. We start with a full assessment, then choose from our services what fits your condition, your goals and your lifestyle.","A plan usually combines manual therapy, therapeutic exercise and education, with regular progress checks."]},"highlights":[{"icon":"SearchCheck","title":{"ar":"تقييم أولاً","en":"Assessment first"},"text":{"ar":"كل خطة تبدأ بفحص دقيق.","en":"Every plan starts with a careful exam."}},{"icon":"Layers","title":{"ar":"علاج متكامل","en":"Integrated care"},"text":{"ar":"أكثر من أسلوب في خطة واحدة.","en":"Several methods in one plan."}},{"icon":"TrendingUp","title":{"ar":"تقدّم ملموس","en":"Visible progress"},"text":{"ar":"قياس منتظم للنتائج.","en":"Results measured regularly."}}],"cardTitle":{"ar":"خطة علاج مخصّصة","en":"Personal treatment plan"},"cardText":{"ar":"متابعة مستمرة","en":"Continuous follow-up"},"image":{"id":"cb24c5cd-6c7f-5d08-a42f-a6723d9d405e","position":""},"secondaryImage":{"id":"6dbd312c-dd39-59b8-85ae-e5c1fd5453c4","position":""}}'::jsonb, null),
  ('a40f4958-69de-5e25-bcd6-b2bd9a1353bf', 'services', 'main', 'servicesGrid', 30, true, '{"heading":{"eyebrow":{"ar":"الخدمات الرئيسية","en":"Main services"},"title":{"ar":"مجالات العلاج الأساسية","en":"Core areas of treatment"},"text":{"ar":"أكثر ما يطلبه مرضانا — بخطط مصمّمة لكل مرحلة من مراحل التعافي.","en":"What our patients ask for most — with plans designed for every stage of recovery."}}}'::jsonb, null),
  ('96bdc55e-4979-5aed-abec-d24b59bc535e', 'services', 'all', 'servicesGrid', 40, true, '{"heading":{"eyebrow":{"ar":"كل الخدمات","en":"All services"},"title":{"ar":"أدوات علاجية متكاملة","en":"A complete therapeutic toolkit"},"text":{"ar":"تُختار الأساليب المناسبة لكل مريض حسب التقييم.","en":"Methods are chosen for each patient based on assessment."}}}'::jsonb, null),
  ('6bb3eca8-04be-5017-bf74-dada396dedbc', 'services', 'conditions', 'conditionsGrid', 50, true, '{"heading":{"eyebrow":{"ar":"الحالات التي نعالجها","en":"Conditions we treat"},"title":{"ar":"من الرقبة حتى الكاحل","en":"From neck to ankle"},"text":{"ar":"أمثلة على الحالات الشائعة التي يساعد فيها العلاج الطبيعي والتأهيل.","en":"Examples of common conditions where physiotherapy and rehabilitation can help."}}}'::jsonb, null),
  ('8743649e-0a4c-5e0e-bd92-8b061a2aa20e', 'services', 'process', 'processTimeline', 60, true, '{"heading":{"eyebrow":{"ar":"مراحل العلاج","en":"Treatment stages"},"title":{"ar":"رحلة واضحة من أول تواصل حتى التعافي","en":"A clear path from first contact to recovery"}}}'::jsonb, null),
  ('272fe724-bdb3-516d-96a1-297b53e67bae', 'services', 'approach', 'approach', 70, true, '{"eyebrow":{"ar":"ما الذي يميّز نهجنا","en":"What makes our approach different"},"title":{"ar":"نعالج السبب، لا العَرَض فقط","en":"Treating the cause, not just the symptom"},"statement":{"ar":"هدفنا أن تحتاجنا أقل مع الوقت — لأنك أصبحت أقوى وأكثر فهماً لجسمك.","en":"Our goal is for you to need us less over time — because you''ve become stronger and understand your body better."},"items":[{"icon":"ScanSearch","title":{"ar":"تشخيص حركي شامل","en":"Whole-body movement assessment"},"text":{"ar":"ننظر إلى طريقة حركة الجسم كاملاً، لا إلى مكان الألم وحده.","en":"We look at how your whole body moves, not only where it hurts."}},{"icon":"Dumbbell","title":{"ar":"علاج نشط","en":"Active treatment"},"text":{"ar":"التمارين في قلب الخطة، لأن القوة هي ما يحميك على المدى الطويل.","en":"Exercise sits at the heart of the plan, because strength is what protects you long-term."}},{"icon":"Gauge","title":{"ar":"تقدّم يُقاس","en":"Measured progress"},"text":{"ar":"نقيس مدى الحركة والقوة والألم بانتظام ونعدّل الخطة بناءً على النتائج.","en":"Range, strength and pain are measured regularly and the plan adjusted to the results."}},{"icon":"BookOpen","title":{"ar":"تعليم المريض","en":"Patient education"},"text":{"ar":"تفهم حالتك وتتعلّم كيف تتعامل معها في حياتك اليومية.","en":"You understand your condition and learn how to manage it day to day."}}]}'::jsonb, null),
