  ('826948a4-d6de-5e04-89c5-73b1bd0f02f8', 'contact', 'channels', 'contactChannels', 20, true, '{"heading":{"eyebrow":{"ar":"طرق التواصل","en":"Ways to reach us"},"title":{"ar":"اختر الطريقة الأنسب لك","en":"Choose what suits you best"},"text":{"ar":"نسعد بالرد على استفساراتك وتحديد موعدك في أقرب وقت.","en":"We''re happy to answer your questions and schedule your visit as soon as possible."}},"phone":{"title":{"ar":"اتصال مباشر","en":"Call directly"},"text":{"ar":"تحدّث معنا لحجز موعد أو للاستفسار.","en":"Speak with us to book or ask a question."},"action":{"ar":"اتصل الآن","en":"Call now"}},"whatsapp":{"title":{"ar":"واتساب","en":"WhatsApp"},"text":{"ar":"أرسل رسالتك وسنرد عليك في أقرب وقت.","en":"Send your message and we''ll reply as soon as we can."},"action":{"ar":"ابدأ المحادثة","en":"Start chat"}},"location":{"title":{"ar":"موقع العيادة","en":"Clinic location"},"text":{"ar":"العنوان","en":"Address"}},"hours":{"title":{"ar":"مواعيد العمل","en":"Working hours"},"text":{"ar":"أيام وساعات الاستقبال","en":"Reception days & times"}}}'::jsonb, null),
