  ('2a4f97bc-57cb-5c7c-b16b-75e28e791c7e', 'contact', 'booking', 'contactForm', 40, true, '{"heading":{"eyebrow":{"ar":"أرسل رسالة","en":"Send a message"},"title":{"ar":"احكِ لنا عن حالتك","en":"Tell us about your condition"},"text":{"ar":"املأ النموذج وسيُفتح واتساب برسالة جاهزة تحتوي على بياناتك لإرسالها مباشرة.","en":"Fill in the form and WhatsApp will open with a ready-made message containing your details."}},"nameLabel":{"ar":"الاسم الكامل","en":"Full name"},"phoneLabel":{"ar":"رقم الهاتف","en":"Phone number"},"reasonLabel":{"ar":"سبب التواصل","en":"Reason for contact"},"reasons":{"ar":["حجز موعد","استفسار عن حالة","متابعة علاج","أخرى"],"en":["Book an appointment","Ask about a condition","Treatment follow-up","Other"]},"messageLabel":{"ar":"اكتب رسالتك (اختياري)","en":"Your message (optional)"},"submitLabel":{"ar":"إرسال عبر واتساب","en":"Send via WhatsApp"},"sentMessage":{"ar":"تم فتح واتساب — أكمل الإرسال من هناك.","en":"WhatsApp opened — finish sending from there."},"requiredMessage":{"ar":"هذا الحقل مطلوب","en":"This field is required"},"privacyNote":{"ar":"لا يتم حفظ بياناتك على الموقع؛ تُرسل مباشرة عبر واتساب.","en":"Your details aren''t stored on this site; they''re sent directly via WhatsApp."},"greeting":{"ar":"مرحباً د. محمد،","en":"Hello Dr. Mohamed,"},"map":{"eyebrow":{"ar":"الموقع","en":"Location"},"title":{"ar":"زيارة العيادة","en":"Visit the clinic"},"pending":{"ar":"ستُضاف الخريطة بعد تحديد عنوان العيادة.","en":"The map will be added once the clinic address is confirmed."}}}'::jsonb, null),
  ('e9c1d450-a046-5332-9abc-7197cf8bc68e', 'global', 'navbar', 'navbar', 10, true, '{"bookCta":{"label":{"ar":"احجز موعدك","en":"Book a Visit"},"href":"/contact#booking"}}'::jsonb, null),
  ('02932dd4-e24f-5de6-b755-271b482616e4', 'global', 'cta', 'siteCta', 20, true, '{"eyebrow":{"ar":"ابدأ اليوم","en":"Start today"},"title":{"ar":"خطوتك الأولى نحو حياة بلا ألم","en":"Your first step toward a pain-free life"},"lines":{"ar":["تقييم دقيق لحالتك، وخطة علاج واضحة تناسب أهدافك.","تواصل الآن عبر واتساب أو اتصل مباشرة لحجز موعدك."],"en":["A precise assessment of your condition and a clear plan built around your goals.","Message us on WhatsApp or call directly to book your visit."]},"showWhatsapp":true,"showCall":true,"whatsappLabel":{"ar":"تواصل عبر واتساب","en":"Chat on WhatsApp"},"callLabel":{"ar":"اتصل الآن","en":"Call now"},"note":{"ar":"أو اتصل مباشرة على","en":"Or call us directly on"},"badge":{"ar":"خطة علاج مخصّصة","en":"Personal treatment plan"},"image":{"id":"c775748d-6423-53ef-ae3b-1eeafb4ccddb","position":""}}'::jsonb, null),
  ('4ee9de16-994f-5e6a-8996-f3eb5b80fcca', 'global', 'footer', 'siteFooter', 30, true, '{"about":{"ar":"طبيب العلاج الطبيعي والتأهيل. نساعدك على تخفيف الألم واستعادة الحركة من خلال خطط علاج مخصّصة ومتابعة مستمرة.","en":"Physiotherapy and rehabilitation doctor. Helping you ease pain and restore movement through personalised treatment plans and continuous follow-up."},"quickLinksTitle":{"ar":"روابط سريعة","en":"Quick links"},"servicesTitle":{"ar":"الخدمات","en":"Services"},"contactTitle":{"ar":"معلومات التواصل","en":"Contact"},"phoneLabel":{"ar":"الهاتف","en":"Phone"},"whatsappLabel":{"ar":"واتساب","en":"WhatsApp"},"whatsappAction":{"ar":"تواصل عبر واتساب","en":"Chat on WhatsApp"},"showServices":true,"servicesCount":6,"rights":{"ar":"جميع الحقوق محفوظة.","en":"All rights reserved."},"backToTop":{"ar":"العودة للأعلى","en":"Back to top"}}'::jsonb, null)
