insert into public.services (id, slug, icon, image_id, featured, sort_order, status, title_ar, title_en, summary_ar, summary_en, points_ar, points_en) values
  ('d10cfb8c-c017-54da-adc5-92538b9baa4d', 'orthopedic', 'Bone', 'd61f2a8b-e72c-5347-8c61-265f30583161', true, 10, 'published', 'تأهيل العظام والمفاصل', 'Orthopaedic & Joint Rehab', 'برامج لاستعادة مدى الحركة والقوة في المفاصل بعد الإصابات أو مع آلام المفاصل المزمنة.', 'Programmes that restore range of motion and strength after injury or with long-standing joint pain.', array['تقييم مدى الحركة والقوة', 'تمارين تقوية تدريجية', 'تحسين الثبات والتوازن']::text[], array['Range & strength assessment', 'Progressive strengthening', 'Stability and balance']::text[]),
  ('6f42d09d-6875-5057-8973-59a89639078e', 'spine', 'Activity', '16a1d42f-4876-5738-82b9-cdd4f8db8f45', true, 20, 'published', 'علاج آلام الظهر والرقبة', 'Back & Neck Pain Care', 'تخفيف آلام العمود الفقري ومعالجة أسبابها عبر العلاج اليدوي والتمارين وتصحيح العادات اليومية.', 'Easing spinal pain and treating its causes through manual therapy, exercise and better daily habits.', array['آلام أسفل الظهر والرقبة', 'تيبّس العضلات', 'الوقاية من تكرار الألم']::text[], array['Low-back and neck pain', 'Muscle stiffness', 'Preventing recurrence']::text[]),
  ('adf51ebf-ba84-58a4-8cba-b8b81a0dd46c', 'sports', 'Dumbbell', 'f68877e4-9d47-5af3-8493-56bf49d59ae2', true, 30, 'published', 'تأهيل الإصابات الرياضية', 'Sports Injury Rehab', 'عودة آمنة ومدروسة إلى الملعب بعد الإصابة، مع برنامج يقلّل خطر تكرارها.', 'A safe, structured return to play after injury — with a programme that lowers the risk of it happening again.', array['الشد والتمزق العضلي', 'إصابات الأربطة', 'خطة عودة تدريجية']::text[], array['Muscle strains and tears', 'Ligament injuries', 'Graded return to sport']::text[]),
  ('f891bcf6-ce0b-5722-9d20-4e3c0e63ffe2', 'post-surgery', 'ClipboardCheck', '8952200c-3175-5df6-8d6f-d8afc09d5847', false, 40, 'published', 'التأهيل بعد العمليات', 'Post-Surgical Rehab', 'متابعة منظّمة بعد الجراحة لاستعادة الحركة والقوة وفق مراحل التعافي.', 'Organised follow-up after surgery to rebuild movement and strength through each stage of recovery.', array['بعد جراحات المفاصل', 'بعد إصلاح الأربطة', 'بعد الكسور']::text[], array['After joint surgery', 'After ligament repair', 'After fractures']::text[]),
  ('344eda05-02b9-583c-8b54-4cdcdef21a14', 'manual', 'Hand', 'c04dbc0e-5772-5f45-8291-c77d4705ceb2', false, 50, 'published', 'العلاج اليدوي', 'Manual Therapy', 'تقنيات يدوية متخصّصة لتحريك المفاصل وإرخاء العضلات وتخفيف الألم.', 'Specialised hands-on techniques to mobilise joints, release muscles and reduce pain.', array['تحريك المفاصل', 'إرخاء الأنسجة الرخوة', 'تحسين المرونة']::text[], array['Joint mobilisation', 'Soft-tissue release', 'Improved flexibility']::text[]),
  ('f4d95b41-5b64-5d6b-9ff7-812f88d62959', 'exercise', 'PersonStanding', '6acc8e0d-df2f-59b1-823d-218b5271f779', false, 60, 'published', 'العلاج بالتمرينات', 'Therapeutic Exercise', 'تمارين علاجية موجّهة تبني القوة والتحكّم الحركي خطوة بخطوة.', 'Guided therapeutic exercise that builds strength and motor control step by step.', array['تقوية العضلات', 'تمارين الثبات', 'التحكّم الحركي']::text[], array['Muscle strengthening', 'Stability training', 'Motor control']::text[]),
  ('ad4b15b6-2d37-5c7f-8694-8b545efa8b70', 'posture', 'Move', 'a913e059-e690-5c58-b828-deaf039f9dab', false, 70, 'published', 'تصحيح القوام', 'Posture Correction', 'تقييم وضعيات الجلوس والوقوف والعمل، وتمارين لتصحيح الاختلالات المسبّبة للألم.', 'Assessing how you sit, stand and work — and correcting the imbalances that cause pain.', array['تقييم القوام', 'بيئة العمل المكتبي', 'تمارين تصحيحية']::text[], array['Postural assessment', 'Desk ergonomics', 'Corrective exercise']::text[]),
  ('bf9d37ac-39b2-5f5e-b23a-caffa84f586b', 'modalities', 'Zap', '78b975b0-ca64-5dde-8471-c7409343a233', false, 80, 'published', 'الأجهزة العلاجية المساعدة', 'Therapeutic Modalities', 'وسائل علاجية مساعدة تُستخدم عند الحاجة لدعم تخفيف الألم ضمن الخطة العلاجية.', 'Supportive treatment modalities, used when appropriate, to help manage pain within the overall plan.', array['حسب تقييم الحالة', 'دعم تخفيف الألم', 'جزء من خطة متكاملة']::text[], array['Based on assessment', 'Pain-relief support', 'Part of a complete plan']::text[]),
  ('80e9b786-58ae-5046-a41c-4b2094ae38e6', 'home-program', 'House', '093e21b4-2fec-58b4-9c4c-13b95c55e53c', false, 90, 'published', 'برامج التمارين المنزلية', 'Home Exercise Programmes', 'برنامج تمارين واضح تتابعه في المنزل بين الجلسات لتسريع التقدّم والحفاظ عليه.', 'A clear exercise plan to follow at home between sessions, speeding up progress and keeping it.', array['تمارين مخصّصة لحالتك', 'شرح وتوضيح عملي', 'متابعة الالتزام']::text[], array['Tailored to your condition', 'Demonstrated clearly', 'Adherence follow-up']::text[])
insert into public.conditions (id, slug, icon, image_id, sort_order, status, region_ar, region_en, text_ar, text_en, items_ar, items_en) values
  ('7a2de340-89cf-521b-8837-576ee3dff6e7', 'back', 'Activity', '16a1d42f-4876-5738-82b9-cdd4f8db8f45', 10, 'published', 'الظهر والعمود الفقري', 'Back & Spine', 'آلام الظهر من أكثر أسباب زيارة أخصائي العلاج الطبيعي. التقييم الدقيق يحدّد مصدر الألم ويرسم طريق العلاج.', 'Back pain is one of the most common reasons to see a physiotherapist. A precise assessment pinpoints the source and maps the way forward.', array['آلام أسفل الظهر', 'الانزلاق الغضروفي', 'عرق النسا', 'تيبّس الظهر']::text[], array['Low-back pain', 'Disc herniation', 'Sciatica', 'Back stiffness']::text[]),
  ('db0db517-08ab-59a5-8b9a-849b27b0324a', 'neck', 'PersonStanding', '74e0101e-ee6c-51e2-872c-18eaee8bb3b6', 20, 'published', 'الرقبة والكتف', 'Neck & Shoulder', 'ساعات العمل الطويلة والهاتف المحمول تضغط على الرقبة والكتفين. نعيد التوازن للعضلات ونحسّن الحركة.', 'Long working hours and phone use load the neck and shoulders. We rebalance the muscles and improve movement.', array['آلام الرقبة', 'الكتف المتجمّد', 'إصابات الكفّة المدوّرة', 'التهاب الأوتار']::text[], array['Neck pain', 'Frozen shoulder', 'Rotator-cuff injuries', 'Tendinopathy']::text[]),
  ('9f4e8ca8-ef43-5825-9931-9ef00f93299c', 'knee', 'Bone', 'b1b90038-356e-5254-b0ff-fd1941e001f3', 30, 'published', 'الركبة والورك', 'Knee & Hip', 'من خشونة المفاصل إلى إصابات الأربطة — نعمل على تقوية العضلات الداعمة وتحسين طريقة الحركة.', 'From joint wear to ligament injuries — we strengthen the supporting muscles and refine how you move.', array['خشونة الركبة', 'إصابات الأربطة', 'آلام الورك', 'آلام الرضفة']::text[], array['Knee osteoarthritis', 'Ligament injuries', 'Hip pain', 'Kneecap pain']::text[]),
  ('bfe983ee-f7e1-540e-9c10-6c78495f2d3d', 'ankle', 'Footprints', 'e72f8580-56b1-5a3f-a361-a3dd4a6ba2a9', 40, 'published', 'القدم والكاحل', 'Foot & Ankle', 'التواءات الكاحل وآلام القدم تؤثر على كل خطوة. التأهيل الصحيح يعيد الثبات ويمنع تكرار الإصابة.', 'Ankle sprains and foot pain affect every step. Proper rehab restores stability and prevents re-injury.', array['التواء الكاحل', 'التهاب اللفافة الأخمصية', 'آلام وتر أخيل', 'ضعف الثبات']::text[], array['Ankle sprain', 'Plantar fasciitis', 'Achilles pain', 'Poor stability']::text[]),
  ('9f634d39-0ea9-5d86-b941-32c8a83d732d', 'sport', 'Dumbbell', '620c816c-b89c-5be2-904a-3ab3b53e05a5', 50, 'published', 'الإصابات الرياضية', 'Sports Injuries', 'خطة تأهيل تراعي متطلبات رياضتك، مع اختبارات واضحة قبل العودة إلى التدريب الكامل.', 'A rehab plan built around the demands of your sport, with clear tests before full return to training.', array['الشدّ العضلي', 'الإصابات المتكرّرة', 'آلام الإجهاد', 'العودة للملاعب']::text[], array['Muscle strains', 'Recurring injuries', 'Overuse pain', 'Return to play']::text[]),
  ('6deb9680-f74b-5911-bfc2-e9f6fed5de4f', 'surgery', 'ClipboardCheck', '7713b0cb-6e19-563a-8de0-649dde6d1612', 60, 'published', 'ما بعد الجراحة', 'After Surgery', 'التأهيل بعد العملية جزء أساسي من نجاحها. نتابع كل مرحلة بالتنسيق مع خطة الطبيب الجرّاح.', 'Post-operative rehab is a core part of a successful surgery. We follow each stage in line with your surgeon''s plan.', array['الرباط الصليبي', 'تغيير المفاصل', 'ما بعد الكسور', 'جراحات الكتف']::text[], array['ACL reconstruction', 'Joint replacement', 'After fractures', 'Shoulder surgery']::text[])
insert into public.process_steps (id, key, icon, sort_order, status, title_ar, title_en, text_ar, text_en) values
  ('8999092b-f291-5792-8563-77cf7a6c2ec6', 'step-1', 'MessageCircle', 10, 'published', 'التواصل والحجز', 'Get in touch', 'تواصل عبر الهاتف أو واتساب، وحدّد موعد التقييم الأول بما يناسبك.', 'Call or message on WhatsApp and choose a time for your first assessment.'),
  ('c8c44d20-8fab-5cce-9aea-a410dc7d5a36', 'step-2', 'SearchCheck', 20, 'published', 'التقييم الشامل', 'Full assessment', 'فحص الحركة والقوة ومراجعة التاريخ المرضي والتقارير لتحديد مصدر المشكلة.', 'Movement and strength testing plus a review of your history and reports to find the real cause.'),
  ('2554170d-360a-5f02-9444-edae4ada0ac4', 'step-3', 'Route', 30, 'published', 'خطة علاج مخصّصة', 'Personal plan', 'أهداف واضحة وجلسات مرتّبة تجمع العلاج اليدوي والتمارين حسب حالتك.', 'Clear goals and structured sessions combining manual therapy and exercise for your condition.'),
  ('d411499b-598c-5d56-b006-b40257474758', 'step-4', 'TrendingUp', 40, 'published', 'المتابعة والوقاية', 'Progress & prevention', 'قياس التقدّم بانتظام، وبرنامج منزلي يحافظ على النتائج ويمنع عودة الألم.', 'Regular progress checks and a home programme that protects your results.')
