insert into public.videos (id, slug, source, youtube_id, video_url, file_id, poster_id, featured, sort_order, status, category_ar, category_en, title_ar, title_en, description_ar, description_en) values
  ('e155c5b8-69d0-5f4f-866c-78ad9fd0ba88', 'exercises-to-ease-low-back-pain', 'youtube', null, null, null, '6acc8e0d-df2f-59b1-823d-218b5271f779', true, 10, 'published', 'الظهر', 'Back', 'تمارين لتخفيف آلام أسفل الظهر', 'Exercises to ease low-back pain', 'مجموعة تمارين بسيطة لتنشيط عضلات الجذع وتخفيف الضغط عن أسفل الظهر.', 'Simple movements that activate your core and take pressure off the lower back.'),
  ('b259b5d8-d988-5f13-a34d-59176cc8defe', 'sitting-well-at-your-desk', 'youtube', null, null, null, 'a913e059-e690-5c58-b828-deaf039f9dab', true, 20, 'published', 'القوام', 'Posture', 'الجلسة الصحيحة أمام المكتب', 'Sitting well at your desk', 'كيف تضبط كرسيك وشاشتك لتقليل إجهاد الرقبة والظهر أثناء العمل.', 'How to set up your chair and screen to reduce neck and back strain at work.'),
  ('bdfaa1a1-caf0-5ac8-af0b-9b3d4923526e', 'strengthening-around-the-knee', 'youtube', null, null, null, '91404a5a-b387-5a91-9f3b-8338badf4cb4', true, 30, 'published', 'الركبة', 'Knee', 'تقوية العضلات حول الركبة', 'Strengthening around the knee', 'تمارين تدريجية تدعم مفصل الركبة وتحسّن الثبات أثناء المشي.', 'Progressive exercises that support the knee joint and steady your walking.'),
  ('f4a71df1-e235-539f-8229-b38cc6e6a872', 'neck-and-shoulder-stretches', 'youtube', null, null, null, 'c50e8331-e185-5709-8523-dec9c74e37fc', false, 40, 'published', 'الرقبة والكتف', 'Neck & Shoulder', 'إطالات الرقبة والكتفين', 'Neck and shoulder stretches', 'إطالات يومية قصيرة لتخفيف التيبّس الناتج عن الجلوس الطويل.', 'Short daily stretches to release stiffness from long hours of sitting.'),
  ('5b87eaa6-8298-59e6-9f07-3573461cd93a', 'balance-and-fall-prevention', 'youtube', null, null, null, 'ee484e84-4396-5a3c-a1a8-08af003ae71c', false, 50, 'published', 'التوازن', 'Balance', 'التوازن والوقاية من السقوط', 'Balance and fall prevention', 'تمارين توازن آمنة تساعد على الثبات وتقليل خطر السقوط.', 'Safe balance drills that build steadiness and reduce the risk of falls.'),
  ('d8e28c8a-baec-5183-bd15-2642d82f811d', 'rehab-after-an-ankle-sprain', 'youtube', null, null, null, 'e72f8580-56b1-5a3f-a361-a3dd4a6ba2a9', false, 60, 'published', 'الكاحل', 'Ankle', 'التأهيل بعد التواء الكاحل', 'Rehab after an ankle sprain', 'مراحل استعادة الحركة والقوة بعد التواء الكاحل خطوة بخطوة.', 'Step-by-step stages to regain movement and strength after a sprain.'),
  ('dc983b17-2cfb-57ae-a88e-9e04843ed2d8', 'warming-up-before-sport', 'youtube', null, null, null, '620c816c-b89c-5be2-904a-3ab3b53e05a5', false, 70, 'published', 'رياضة', 'Sport', 'الإحماء الصحيح قبل الرياضة', 'Warming up before sport', 'روتين إحماء يجهّز العضلات والمفاصل ويقلّل خطر الإصابة.', 'A warm-up routine that prepares muscles and joints and lowers injury risk.'),
  ('3429dc7c-fd4d-5ef3-b9e7-0cec4a715f8a', 'core-stability-basics', 'youtube', null, null, null, 'ec22c78c-e513-5209-b91e-46025076f79f', false, 80, 'published', 'الجذع', 'Core', 'تمارين ثبات الجذع', 'Core stability basics', 'أساسيات تقوية عضلات الجذع لدعم العمود الفقري في الحركة اليومية.', 'Foundations of core strength to support your spine in everyday movement.'),
  ('62a9a950-4732-5df8-b216-c45572e96301', 'what-happens-at-your-first-visit', 'youtube', null, null, null, '983a1efc-1e14-5684-aadd-53edf805a2f4', false, 90, 'published', 'توعية', 'Awareness', 'ماذا يحدث في جلستك الأولى؟', 'What happens at your first visit?', 'جولة سريعة على خطوات التقييم الأول وما يمكن أن تتوقعه.', 'A quick walkthrough of the first assessment and what to expect.')
insert into public.articles (id, slug, category_id, cover_id, og_image_id, published_on, featured, sort_order, status, title_ar, title_en, excerpt_ar, excerpt_en, author_ar, author_en, cover_alt_ar, cover_alt_en, body_ar, body_en, seo_title_ar, seo_title_en, seo_description_ar, seo_description_en) values
  ('f1347960-89c9-5f5a-ae0e-4cc62ba45588', 'low-back-pain', '0f361fc5-8819-5892-859a-0509a9d0f9f2', '16a1d42f-4876-5738-82b9-cdd4f8db8f45', null, null, true, 10, 'published', 'آلام أسفل الظهر: متى تحتاج إلى العلاج الطبيعي؟', 'Low-back pain: when should you see a physiotherapist?', 'ألم أسفل الظهر شائع جداً، ومعظم حالاته تتحسّن بالحركة الصحيحة. تعرّف على العلامات التي تستدعي التقييم، وما الذي يقدّمه العلاج الطبيعي لك.', 'Low-back pain is very common, and most cases improve with the right movement. Learn the signs that call for an assessment — and what physiotherapy can do for you.', '', '', '', '', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"يعاني معظم الناس من ألم أسفل الظهر في مرحلة ما من حياتهم. في كثير من الحالات يكون الألم مرتبطاً بإجهاد العضلات أو الجلوس الطويل أو ضعف عضلات الجذع، ويتحسّن مع الحركة المدروسة."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"متى يُنصح بالتقييم؟"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"استمرار الألم لأكثر من بضعة أسابيع"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ألم يمتد إلى الساق أو يصاحبه تنميل"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ألم يتكرّر ويؤثر على عملك أو نومك"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"صعوبة في أداء الأنشطة اليومية المعتادة"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"كيف يساعد العلاج الطبيعي؟"}]},{"type":"paragraph","content":[{"type":"text","text":"يبدأ العلاج بتقييم دقيق للحركة والقوة والوضعيات، ثم خطة تجمع بين العلاج اليدوي وتمارين التقوية والإطالة، مع نصائح عملية لتعديل العادات اليومية التي تزيد الألم."}]},{"type":"paragraph","content":[{"type":"text","text":"الهدف ليس تخفيف الألم مؤقتاً فقط، بل بناء ظهر أقوى وأكثر قدرة على التحمّل لتقليل فرص عودة الألم."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most people experience low-back pain at some point. Often it is linked to muscle strain, long periods of sitting or a weak core — and it improves with well-planned movement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When is an assessment recommended?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pain lasting more than a few weeks"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pain spreading into the leg, or with numbness"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pain that keeps returning and affects work or sleep"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Difficulty with your usual daily activities"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How does physiotherapy help?"}]},{"type":"paragraph","content":[{"type":"text","text":"Treatment starts with a careful assessment of movement, strength and posture, followed by a plan combining manual therapy, strengthening and stretching, plus practical advice on the daily habits that aggravate pain."}]},{"type":"paragraph","content":[{"type":"text","text":"The aim is not just short-term relief, but a stronger, more resilient back that is less likely to hurt again."}]}]}'::jsonb, '', '', '', ''),
  ('ec883859-d6a0-504b-99da-84b07d1c0361', 'desk-posture', '783bc0f3-e71c-58bc-a5fe-d33b31b64ae2', 'a913e059-e690-5c58-b828-deaf039f9dab', null, null, false, 20, 'published', 'الجلوس الصحيح أمام المكتب', 'Sitting well at your desk', 'تعديلات بسيطة في الكرسي والشاشة وطريقة الجلوس قد تصنع فرقاً كبيراً في آلام الرقبة والظهر.', 'Small changes to your chair, screen and sitting habits can make a big difference to neck and back pain.', '', '', '', '', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"قضاء ساعات طويلة أمام الشاشة يضع ضغطاً متكرّراً على الرقبة والكتفين وأسفل الظهر. الخبر الجيد أن تعديلات بسيطة يمكن أن تخفّف هذا الضغط بشكل ملحوظ."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"اجعل أعلى الشاشة في مستوى العين تقريباً"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"اسند ظهرك بالكامل على الكرسي"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"قدماك مسطّحتان على الأرض والركبتان بزاوية مريحة"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"قف وتحرّك لدقيقتين كل نصف ساعة"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"أفضل وضعية هي الوضعية التالية — أي أن تغيير الوضعية والحركة المنتظمة أهم من الثبات على وضعية مثالية واحدة."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hours in front of a screen put repeated load on the neck, shoulders and lower back. The good news: simple adjustments can noticeably reduce it."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep the top of the screen roughly at eye level"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Let the chair fully support your back"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Feet flat on the floor, knees at a comfortable angle"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stand and move for two minutes every half hour"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The best posture is your next posture — changing position and moving regularly matters more than holding one perfect position."}]}]}'::jsonb, '', '', '', ''),
  ('6a04d421-7ddc-58bc-ba0d-396803018d1a', 'return-to-sport', 'ff09f7ca-0201-585b-877e-0ebf4d7bbf00', '620c816c-b89c-5be2-904a-3ab3b53e05a5', null, null, false, 30, 'published', 'العودة إلى الرياضة بعد الإصابة', 'Returning to sport after injury', 'العودة المبكرة قد تعني إصابة جديدة. كيف تعرف أن جسمك جاهز فعلاً للتدريب الكامل؟', 'Going back too early can mean a new injury. How do you know your body is truly ready for full training?', '', '', '', '', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"اختفاء الألم لا يعني دائماً أن العضلة أو الرباط استعادا قوتهما الكاملة. العودة المدروسة تعتمد على معايير واضحة لا على الإحساس وحده."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"استعادة مدى الحركة الكامل"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"قوة متقاربة بين الطرفين"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"القدرة على أداء حركات رياضتك دون ألم"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ثقة نفسية بالحركة"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"برنامج التأهيل الرياضي يتدرّج من التمارين الأساسية إلى حركات الرياضة نفسها، ليقلّل خطر تكرار الإصابة."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pain disappearing doesn''t always mean the muscle or ligament has regained full strength. A safe return relies on clear criteria, not feeling alone."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Full range of motion restored"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Similar strength on both sides"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sport-specific movements without pain"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Confidence in the movement"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Sports rehab progresses from basic exercises to the movements of your sport itself, reducing the risk of re-injury."}]}]}'::jsonb, '', '', '', ''),
  ('6c17f649-9223-5c31-ba6c-ba58f7c02a8d', 'knee-osteoarthritis', '7b952769-1fb2-5b84-a50f-2c86385ef95a', 'b1b90038-356e-5254-b0ff-fd1941e001f3', null, null, false, 40, 'published', 'خشونة الركبة والحركة اليومية', 'Knee osteoarthritis and daily movement', 'هل يجب أن تتوقف عن الحركة مع خشونة الركبة؟ غالباً العكس هو الصحيح.', 'Should you stop moving with knee osteoarthritis? Usually, the opposite is true.', '', '', '', '', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"خشونة الركبة من الحالات الشائعة مع التقدّم في العمر. يعتقد كثيرون أن الراحة التامة هي الحل، لكن الحركة المناسبة غالباً ما تكون جزءاً أساسياً من العلاج."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تقوية عضلات الفخذ لدعم المفصل"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تمارين منخفضة التأثير مثل المشي والدراجة الثابتة"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"الحفاظ على وزن صحي"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تعديل الأنشطة التي تزيد الألم"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"يساعدك أخصائي العلاج الطبيعي على اختيار التمارين المناسبة لحالتك ومستوى نشاطك."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Knee osteoarthritis is common with age. Many believe complete rest is the answer, but appropriate movement is usually a key part of treatment."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Strengthen the thigh muscles to support the joint"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose low-impact activity such as walking or a stationary bike"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Maintain a healthy weight"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adapt activities that increase pain"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A physiotherapist helps you choose the right exercises for your condition and activity level."}]}]}'::jsonb, '', '', '', ''),
  ('d8f4a18f-7b6c-500c-8640-09c00632994b', 'post-surgery-rehab', '147570ca-a57f-5840-899c-ea2ac5e98e43', '7713b0cb-6e19-563a-8de0-649dde6d1612', null, null, false, 50, 'published', 'لماذا لا تكتمل الجراحة دون تأهيل؟', 'Why surgery isn''t complete without rehab', 'نجاح العملية يعتمد كثيراً على ما يحدث بعدها. تعرّف على دور التأهيل في كل مرحلة.', 'A successful operation depends a lot on what happens afterwards. Here''s the role rehab plays at each stage.', '', '', '', '', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"بعد جراحات المفاصل والأربطة، يحتاج الجسم إلى إعادة بناء الحركة والقوة تدريجياً. هنا يأتي دور التأهيل المنظّم."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"المرحلة الأولى: التحكّم في التورّم واستعادة الحركة الأساسية"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"المرحلة الثانية: بناء القوة والثبات"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"المرحلة الثالثة: العودة إلى الأنشطة اليومية والرياضية"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"يتم كل ذلك بالتنسيق مع تعليمات الطبيب الجرّاح وحسب طبيعة العملية."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After joint and ligament surgery, the body needs to rebuild movement and strength gradually. That is where structured rehabilitation comes in."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stage one: control swelling and recover basic movement"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stage two: build strength and stability"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stage three: return to daily and sporting activities"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"All of this is coordinated with your surgeon''s instructions and the nature of the operation."}]}]}'::jsonb, '', '', '', ''),
  ('0f8e267e-dbe7-5763-9946-a25f6624cbbc', 'text-neck', '35f7b7e7-3d5b-5b1d-b423-5d724263729d', '74e0101e-ee6c-51e2-872c-18eaee8bb3b6', null, null, false, 60, 'published', 'آلام الرقبة والهاتف المحمول', 'Neck pain and your smartphone', 'انحناء الرأس نحو الشاشة لساعات يومياً يرهق الرقبة. إليك عادات بسيطة لحمايتها.', 'Bending your head toward a screen for hours each day strains the neck. Simple habits to protect it.', '', '', '', '', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"كلما انحنى الرأس إلى الأمام زاد الحمل على عضلات الرقبة وأعلى الظهر. مع الوقت قد يظهر التيبّس والصداع وآلام الكتفين."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ارفع الهاتف إلى مستوى العين بدلاً من خفض الرأس"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"خذ فواصل قصيرة متكرّرة"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"مارس إطالات بسيطة للرقبة والصدر"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"قوِّ عضلات أعلى الظهر"}]}]}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The further the head tilts forward, the more load falls on the neck and upper back. Over time, stiffness, headaches and shoulder pain can follow."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Raise the phone to eye level instead of dropping your head"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Take short, frequent breaks"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Do simple neck and chest stretches"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Strengthen your upper-back muscles"}]}]}]}]}'::jsonb, '', '', '', ''),
  ('28cf067a-3875-5f07-ae20-e82ad0a46040', 'home-exercise', '3fd45aef-3a83-5205-9867-b8a7f75271ea', '093e21b4-2fec-58b4-9c4c-13b95c55e53c', null, null, false, 70, 'published', 'كيف تلتزم ببرنامج التمارين المنزلية؟', 'How to stick with your home exercise programme', 'التمارين المنزلية تصنع جزءاً كبيراً من التقدّم. نصائح عملية لتجعلها عادة يومية.', 'Home exercise drives much of your progress. Practical tips to turn it into a daily habit.', '', '', '', '', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ما تفعله بين الجلسات لا يقلّ أهمية عن الجلسة نفسها. الالتزام بالتمارين المنزلية يسرّع التقدّم ويحافظ على النتائج."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"اربط التمارين بعادة ثابتة في يومك"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ابدأ بعدد قليل وزد تدريجياً"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"سجّل تقدّمك في ورقة أو تطبيق"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"اسأل عن أي تمرين غير واضح"}]}]}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What you do between sessions matters as much as the session itself. Sticking with home exercises speeds up progress and protects your results."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Link exercises to a fixed daily habit"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Start small and build up gradually"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Track progress on paper or in an app"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ask about any exercise that isn''t clear"}]}]}]}]}'::jsonb, '', '', '', '')
insert into public.testimonials (id, key, rating, avatar_id, is_placeholder, sort_order, status, quote_ar, quote_en, name_ar, name_en, meta_ar, meta_en) values
