insert into public.faqs (id, group_key, sort_order, status, question_ar, question_en, answer_ar, answer_en) values
  ('596165c3-17cd-5848-9861-d10cf78dc08d', 'home', 10, 'published', 'كيف أحجز موعداً؟', 'How do I book an appointment?', 'يمكنك الحجز بالاتصال الهاتفي أو بإرسال رسالة عبر واتساب، وسيتم تأكيد الموعد المناسب لك.', 'Call us or send a WhatsApp message, and we''ll confirm a time that suits you.'),
  ('d2e5aadb-8532-5c22-b4d3-250d87b6ecb6', 'home', 20, 'published', 'ماذا أُحضر معي في الزيارة الأولى؟', 'What should I bring to my first visit?', 'أحضر أي تقارير طبية أو صور أشعة أو تحاليل سابقة متعلّقة بحالتك، وارتدِ ملابس مريحة تسمح بالحركة.', 'Bring any medical reports, scans or test results related to your condition, and wear comfortable clothes that let you move.'),
  ('721ccf6c-f798-5d28-90a6-dec9a09c6492', 'home', 30, 'published', 'كم عدد الجلسات التي سأحتاجها؟', 'How many sessions will I need?', 'يختلف ذلك من حالة لأخرى. بعد التقييم الأول نضع معك خطة واضحة بعدد تقريبي للجلسات ونراجعها حسب تقدّمك.', 'It varies by case. After the first assessment we agree a clear plan with an approximate number of sessions and review it as you progress.'),
  ('78930f3e-6201-5793-9dfe-ef23d04ed2c1', 'home', 40, 'published', 'هل العلاج الطبيعي مؤلم؟', 'Is physiotherapy painful?', 'الهدف هو تخفيف الألم لا زيادته. قد تشعر بإجهاد عضلي بسيط بعد بعض التمارين، وهو أمر طبيعي ونراعيه في تدرّج الخطة.', 'The goal is to reduce pain, not add to it. You may feel mild muscle fatigue after some exercises — that''s normal, and we pace the plan accordingly.'),
  ('c21f0a43-1ebb-5434-bd2e-5d65ef8db8fb', 'home', 50, 'published', 'هل أحتاج إلى تمارين في المنزل؟', 'Will I need to exercise at home?', 'نعم غالباً. البرنامج المنزلي جزء مهم من العلاج، وسنشرح لك كل تمرين بوضوح.', 'Usually, yes. A home programme is an important part of treatment, and we''ll explain every exercise clearly.'),
  ('2e43015b-63aa-5d87-a420-a7e8439f1cc4', 'services', 10, 'published', 'كيف أعرف الخدمة المناسبة لحالتي؟', 'How do I know which service I need?', 'لا تحتاج إلى اختيار الخدمة بنفسك. التقييم الأول يحدّد الأساليب المناسبة لحالتك وتُبنى الخطة على أساسه.', 'You don''t need to choose yourself. The first assessment determines the right methods for your condition and the plan is built from it.'),
  ('c44a96d1-22fa-5333-90b5-7135247937da', 'services', 20, 'published', 'هل أحتاج إلى تحويل من طبيب آخر؟', 'Do I need a referral from another doctor?', '[[وضّح سياسة العيادة بخصوص التحويل الطبي.]]', '[[Clarify the clinic''s referral policy.]]'),
  ('80ad6603-6761-5071-a3e0-3c71308f5eab', 'services', 30, 'published', 'كم مدة الجلسة الواحدة؟', 'How long is a session?', '[[حدّد المدة المعتادة للجلسة.]]', '[[State the usual session length.]]'),
  ('e15f2a8e-0bd4-578f-820e-739433c921d5', 'services', 40, 'published', 'هل تتابعون الحالات بعد العمليات الجراحية؟', 'Do you treat patients after surgery?', 'نعم، ويتم التأهيل وفق مراحل التعافي وبالتنسيق مع تعليمات الطبيب الجرّاح.', 'Yes. Rehabilitation follows the stages of recovery, in coordination with your surgeon''s instructions.'),
  ('9e81e5cf-0b1f-50b6-88cf-e23e915e54b7', 'services', 50, 'published', 'هل يمكن المتابعة عن بُعد؟', 'Is remote follow-up available?', '[[وضّح إن كانت الاستشارات أو المتابعة عن بُعد متاحة.]]', '[[Clarify whether online consultations or remote follow-up are offered.]]')
